export type TripStatus = 'Pendiente' | 'Asignado' | 'En camino' | 'En entrega' | 'Completado' | 'Cancelado' | 'Anulado'
export type TripServiceMode = 'Envíos' | 'Taxi Privado'
export type TripTransport = 'Moto' | 'Vehículo' | 'Pickup' | 'VAN' | 'Camión'
export type TripOptionKind = 'option' | 'vehicle'
export type TripOptionService = 'delivery' | 'taxi' | 'cargo'
export type TripOptionPricing = 'flat' | 'per_km' | 'per_hour'

export interface TripStop {
  id?: string
  label: string
  address: string
  latitude?: number
  longitude?: number
  refs?: string
  order: number
  recipientName?: string
  recipientPhone?: string
}

export interface TripOptionSelection {
  code: string
  title: string
  description?: string
  priceCs: number
  currency?: 'NIO' | 'USD'
  quantity?: number
}
export type DriverStatus = 'Disponible' | 'En viaje' | 'En entrega' | 'Fuera de servicio'
export type IncidentPriority = 'Baja' | 'Media' | 'Alta' | 'Crítica'
export type IncidentStatus = 'Abierta' | 'En proceso' | 'Resuelta'

export interface Trip {
  id: string
  profileId?: string
  client: string
  driver: string
  origin: string
  destination: string
  date: string
  packages: number
  status: TripStatus
  completedAt?: string
  latitude?: number
  longitude?: number
  description?: string
  recipientName?: string
  recipientPhone?: string
  fragile?: boolean
  originLat?: number
  originLng?: number
  destinationLat?: number
  destinationLng?: number
  distanceKm?: number
  estimatedCostCs?: number
  costCs?: number
  profitCs?: number
  serviceType?: 'Urbano' | 'Express' | 'Programado'
  serviceMode?: TripServiceMode
  transport?: TripTransport
  vehicleVariant?: string
  truckType?: string
  passengerCount?: number
  returnTrip?: boolean
  stops?: TripStop[]
  options?: TripOptionSelection[]
  optionsTotalCs?: number
  quotedBaseCs?: number
  quotedAdditionalCs?: number
  quotedServiceTotalCs?: number
  contactName?: string
  contactPhone?: string
  pickupTime?: string
  originRefs?: string
  destinationRefs?: string
  scheduledDate?: string
  scheduledTime?: string
  isScheduled?: boolean
  weight?: number
  weightUnit?: 'kg' | 'lb'
  paymentMethod?: 'Efectivo' | 'Transferencia' | 'Tarjeta' | 'Financiamiento' | 'Contra entrega' | ''
  paymentRef?: string
  paymentAmount?: number
  paymentDate?: string
  paymentStatus?: 'Sin pagar' | 'Parcial' | 'Pagado' | 'Crédito'
  dueDate?: string
  cancelReason?: string
}

export const VEHICLE_MAX_WEIGHT_KG: Partial<Record<TripTransport, number>> = {
  Moto: 10,
  Vehículo: 400,
  VAN: 650,
  Pickup: 900,
}

export function maxWeightKgForTransport(transport?: TripTransport) {
  return transport ? VEHICLE_MAX_WEIGHT_KG[transport] : undefined
}

